import json
def walk(o,p=''):
  if isinstance(o,dict):
    for k,v in o.items(): yield from walk(v,p+'.'+k)
  elif isinstance(o,list):
    for i,v in enumerate(o): yield from walk(v,p+'[%d]'%i)
  else: yield p,o
for f in ['fts-awards-page1.json','fts-awards-2025-03-03.json']:
  d=json.load(open('products/services/software-renewals/raw/'+f))
  n=[(r['id'],p,v) for r in d['releases'] for p,v in walk(r) if p.lower().endswith(('enddate','maxextentdate','durationindays'))]
  print(f,len(d['releases']),'end/duration fields:',len(n),n[:10])
